mapper.select:
SELECT ar.employee_id, e.department_id, v.document_id
FROM archive_version v
JOIN archive_document d ON d.id = v.document_id AND d.status = 'ACTIVE'
JOIN archive_record ar ON ar.id = d.archive_record_id AND ar.status = 'ACTIVE'
JOIN employee e ON e.id = ar.employee_id AND e.status = 'ACTIVE'
WHERE v.id = #{id}

    AND 1 = 1
    AND e.department_id = #{departmentId}
    AND e.id = #{employeeId}
    AND 1 = 0

SELECT d.id AS document_id, ar.employee_id, d.document_type, d.title, d.status AS document_status, v.id AS latest_version_id, v.version_no AS latest_version_no, f.original_name AS latest_file_name, f.content_type AS latest_content_type, f.size_bytes AS latest_size, d.created_at AS document_created_at FROM archive_document d JOIN archive_record ar ON ar.id = d.archive_record_id AND ar.status = 'ACTIVE' JOIN employee e ON e.id = ar.employee_id AND e.status = 'ACTIVE' LEFT JOIN archive_version v ON v.id = ( SELECT newest.id FROM archive_version newest WHERE newest.document_id = d.id ORDER BY newest.version_no DESC, newest.id DESC LIMIT 1 ) LEFT JOIN file_object f ON f.id = v.file_object_id WHERE d.status = 'ACTIVE' AND ar.employee_id = #{employeeId}
AND 1 = 1 AND e.department_id = #{departmentId} AND e.id = #{scopeEmployeeId} AND 1 = 0
ORDER BY d.id DESC

SELECT v.id AS version_id, v.document_id, v.version_no, v.status AS version_status, f.original_name, f.content_type, f.size_bytes, f.sha256, v.created_by, v.created_at AS version_created_at FROM archive_version v JOIN file_object f ON f.id = v.file_object_id JOIN archive_document d ON d.id = v.document_id AND d.status = 'ACTIVE' JOIN archive_record ar ON ar.id = d.archive_record_id AND ar.status = 'ACTIVE' JOIN employee e ON e.id = ar.employee_id AND e.status = 'ACTIVE' WHERE v.document_id = #{documentId}
AND 1 = 1 AND e.department_id = #{departmentId} AND e.id = #{scopeEmployeeId} AND 1 = 0
ORDER BY v.version_no DESC, v.id DESC
